/**
 * `.dockerignore` for the build context of a container (its project folder), DEV-4027.
 *
 * The folder holds `code/` (the clone), the generated `Dockerfile` and `docker-compose.yml`, and,
 * for external registries, `.docker/config.json` with the push credentials. Only `.docker` is
 * excluded: it never belongs in an image. `code/` stays complete on purpose, including `.git` and
 * `.env`, because install and build commands of existing projects may rely on them.
 */
export function getBuildContextDockerignore(): string {
  return [
    '# Generated by deploy.party (DEV-4027). Registry credentials never belong in an image.',
    '.docker',
    '',
  ].join('\n');
}
